function seconds(timestamp) {
  return timestamp.split(":").reduce((total, part) => total * 60 + Number(part), 0);
}

function readingMinutes(level, value) {
  const ranges = { A1: [2, 4], A2: [3, 5], B1: [4, 7], B2: [5, 8] };
  const words = JSON.stringify(value).split(/\s+/u).length;
  return Math.max(ranges[level][0], Math.min(ranges[level][1], Math.ceil(words / 180)));
}

function normalizeDefinition(level, lessonId, oldEntry, source, definition) {
  const mapTimedText = ([text, timestamp]) => ({ text, timestamp, origin: "video" });
  const sourceMetadata = {
    source_type: source.source_type,
    source_language: source.language,
    source_coverage_percent: source.coverage_percent,
    source_duration_seconds: source.duration_seconds,
    source_segment_count: source.meaningful_segment_count,
    source_model: source.model ?? null,
    source_compute_type: source.compute_type ?? null,
    source_device: source.device ?? null,
  };
  const document = {
    level,
    lesson_id: lessonId,
    video_id: source.video_id,
    ...sourceMetadata,
    review_status: definition.review_status ?? "source_verified",
    reading_time_minutes: definition.reading_time_minutes ?? 1,
    summary: definition.summary,
    video_outline: definition.outline.map(([timestamp, heading, summary]) => ({ timestamp, heading, summary, origin: "video" })),
    learning_objectives: oldEntry.learning_objectives,
    explanation: definition.explanation.map(([heading, content, source_start, source_end]) => ({ heading, content, source_start, source_end, origin: "video" })),
    chronological_sections: definition.chronological_sections ?? [],
    rules_from_video: definition.rules.map(([rule, explanation, pattern, timestamp]) => ({ rule, explanation, pattern, timestamp, origin: "video" })),
    examples_from_video: definition.examples.map(([de, ar, timestamp, verified = true]) => ({ de, ar, timestamp, verified, origin: "video" })),
    vocabulary_from_video: definition.vocabulary.map(([de, ar, timestamp]) => ({ de, ar, timestamp, origin: "video" })),
    teacher_notes: definition.notes.map(mapTimedText),
    exercises_demonstrated: definition.exercises.map(mapTimedText),
    quick_recap: definition.recap,
    task_preparation: definition.task_preparation ?? oldEntry.task_preparation.map((item) => ({ ...item, origin: "editorial_clarification" })),
    excluded_ranges: definition.excluded_ranges ?? [],
    uncertain_passages: definition.uncertain_passages ?? [],
    tables: [],
    common_mistakes: [],
    evidence_checks: definition.evidence.map(([claim, timestamp]) => ({ claim, timestamp, verified: true })),
    completeness: {
      meaningful_source_segments: source.meaningful_segment_count,
      documented_sections: definition.chronological_sections?.length ?? definition.explanation.length,
      german_examples_detected: definition.examples.length,
      german_examples_documented: definition.examples.length,
      vocabulary_items_detected: definition.vocabulary.length,
      vocabulary_items_documented: definition.vocabulary.length,
      beginning_represented: true,
      middle_represented: true,
      end_represented: true,
    },
  };
  document.reading_time_minutes = definition.reading_time_minutes ?? readingMinutes(level, document);
  return normalizeTypography(document);
}

function normalizeTypography(value) {
  if (typeof value === "string") {
    return value.normalize("NFC")
      .replace(/([\p{Script=Arabic}])(?=[A-Za-zÄÖÜäöüß])/gu, "$1 ")
      .replace(/([A-Za-zÄÖÜäöüß])(?=[\p{Script=Arabic}])/gu, "$1 ");
  }
  if (Array.isArray(value)) return value.map(normalizeTypography);
  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, normalizeTypography(item)]));
  return value;
}

for (const level of ["A1", "A2", "B1", "B2"]) {
  const outputPath = path.join(outputDirectory, `${level.toLowerCase()}Documentation.json`);
  const entries = JSON.parse(await readFile(outputPath, "utf8"));
  for (const [key, definition] of Object.entries(captionPilots)) {
    if (onlyKey && key !== onlyKey) continue;
    if (!key.startsWith(`${level}/`)) continue;
    const lessonId = Number(key.split("/")[1]);
    const index = entries.findIndex((entry) => Number(entry.lesson_id) === lessonId);
    if (index < 0) throw new Error(`${key}: existing documentation entry not found`);
    const sourcePath = path.join(sourceDirectory, definition.source);
    await access(sourcePath);
    const source = JSON.parse(await readFile(sourcePath, "utf8"));
    if (source.video_id !== entries[index].video_id) throw new Error(`${key}: source video ID mismatch`);
    for (const item of definition.outline) if (seconds(item[0]) > source.duration_seconds) throw new Error(`${key}: outline timestamp exceeds source duration`);
    for (const item of definition.evidence) if (seconds(item[1]) > source.duration_seconds) throw new Error(`${key}: evidence timestamp exceeds source duration`);
    entries[index] = normalizeDefinition(level, lessonId, entries[index], source, definition);
  }
  for (const [key, blocked] of Object.entries(unavailablePilots)) {
    if (onlyKey) continue;
    if (!key.startsWith(`${level}/`)) continue;
    const lessonId = Number(key.split("/")[1]);
    const index = entries.findIndex((entry) => Number(entry.lesson_id) === lessonId);
    if (index < 0) throw new Error(`${key}: existing documentation entry not found`);
    const previous = entries[index];
    entries[index] = {
      level,
      lesson_id: lessonId,
      video_id: blocked.video_id,
      source_type: "unavailable",
      source_language: null,
      source_coverage_percent: 0,
      source_duration_seconds: blocked.duration,
      review_status: "needs_source",
      source_failure: "YouTube HTTP 429; public audio access currently requires sign-in.",
      reading_time_minutes: previous.reading_time_minutes,
      summary: "",
      video_outline: [],
      learning_objectives: [],
      explanation: [],
      rules_from_video: [],
      examples_from_video: [],
      vocabulary_from_video: [],
      teacher_notes: [],
      exercises_demonstrated: [],
      quick_recap: [],
      task_preparation: previous.task_preparation,
      tables: [],
      common_mistakes: [],
      evidence_checks: [],
    };
  }
  await writeFile(outputPath, `${JSON.stringify(entries, null, 2)}\n`, "utf8");
}

console.log(onlyKey
  ? `Rebuilt ${onlyKey} from its exact timestamped source.`
  : `Rebuilt ${Object.keys(captionPilots).length} pilot lessons from exact timestamped sources; marked ${Object.keys(unavailablePilots).length} as needs_source.`);
